'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-object' );
var Encoding = require( '@stdlib/plot/vega/mark/arc/encoding' );


// MAIN //

/**
* Tests whether an input value is an arc mark encoding.
*
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is an arc mark encoding
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var EncodingSet = require( '@stdlib/plot/vega/mark/arc/encoding-set' );
* var Encoding = require( '@stdlib/plot/vega/mark/arc/encoding' );
*
* var v = new Encoding({
*     'update': new EncodingSet({
*         'x': new Value({
*             'field': 'x',
*             'scale': 'xScale'
*         })
*     })
* });
* var bool = isArcMarkEncoding( v );
* // returns true
*
* bool = isArcMarkEncoding( {} );
* // returns false
*
* bool = isArcMarkEncoding( 'foo' );
* // returns false
*/
function isArcMarkEncoding( value ) {
	return (
		value instanceof Encoding ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			value.constructor.name === 'ArcEncoding'
		)
	);
}


// EXPORTS //

module.exports = isArcMarkEncoding;
